 ["Locomotion & footsteps by armor weight, mount strides, weather, swimming drag, parry/blocks, full loot/quest haptics"] = "按护甲重量区分的移动与脚步震动、坐骑步伐、天气、游泳阻力、招架/格挡、完整的拾取/任务触感",
 ["Locomotion clatter, weapon swings, loot popups, world dialogs"] = "移动声响、武器挥动、拾取弹窗、世界对话",
 ["Loot & inventory"] = "拾取与背包",
