 ["Rename"] = "重命名",
 ["Rename \"%s\" to:"] = "将“%s”重命名为：",
 ["Rename the profile in use. Every rule pointing at it follows the rename. Built-in profiles can't be renamed."] = "重命名当前使用的配置文件。指向它的所有规则都会同步更新。内置配置文件无法重命名。",
